import test from 'node:test';
import assert from 'node:assert/strict';
import { parseForm, parseJsonWebhook, signForm, verifyForm, statusCallbackUrl, signedWebhookUrl } from '../src/signature.js';
import { createConfig } from '../src/config.js';
import { ENV } from '../test-support/helpers.js';

// Independent published Compatibility vector, not generated by this service:
// https://www.twilio.com/docs/usage/security#validating-requests
const fixture = {
  key: '12345', url: 'https://example.com/myapp.php?foo=1&bar=2', signature: 'L/OH5YylLD5NRKLltdqwSvS0BnU=',
  form: { Digits: '1234', To: '+18005551212', From: '+14158675310', Caller: '+14158675310', CallSid: 'CA1234567890ABCDE' },
};

test('independent known form signature and both header names', () => {
  assert.equal(signForm(fixture.key, fixture.url, fixture.form), fixture.signature);
  for (const header of ['x-signalwire-signature', 'x-twilio-signature']) assert.equal(verifyForm(fixture.key, fixture.url, fixture.form, { [header]: fixture.signature }), true);
  for (const [url, form, headers] of [[fixture.url, fixture.form, {}], [fixture.url, fixture.form, { 'x-signalwire-signature': 'bad' }], [`${fixture.url}&extra=1`, fixture.form, { 'x-signalwire-signature': fixture.signature }], [fixture.url, { ...fixture.form, Extra: 'included' }, { 'x-signalwire-signature': fixture.signature }], [fixture.url, { ...fixture.form, Digits: '1235' }, { 'x-signalwire-signature': fixture.signature }]]) assert.equal(verifyForm(fixture.key, url, form, headers), false);
});

test('all decoded form fields are included; repeated keys rejected explicitly', () => {
  assert.equal(parseForm('From=%2B12025550100&Body=a%2Bb+text').Body, 'a+b text');
  assert.throws(() => parseForm('From=a&From=a'), /Repeated/);
  assert.equal(parseForm('__proto__=safe').__proto__, 'safe');
});

test('flat webhook JSON preserves text and normalizes integer counts/error codes', () => {
  const payload = parseJsonWebhook('{"From":"+12025550100","Body":"a+b text","NumMedia":0,"NumSegments":1,"ErrorCode":30003,"__proto__":"safe"}');
  assert.equal(payload.From, '+12025550100');
  assert.equal(payload.Body, 'a+b text');
  assert.equal(payload.NumMedia, '0');
  assert.equal(payload.NumSegments, '1');
  assert.equal(payload.ErrorCode, '30003');
  assert.equal(payload.__proto__, 'safe');
  for (const text of ['{invalid', 'null', '[]', '"text"', '{"Body":12}', '{"Body":null}', '{"From":{}}', '{"NumMedia":-1}', '{"NumMedia":1.5}']) assert.throws(() => parseJsonWebhook(text), error => error.statusCode === 400);
});

test('optional null JSON error fields do not reject a successful status callback', () => {
  const parsed = parseJsonWebhook('{"MessageStatus":"sent","ErrorCode":null,"ErrorMessage":null}');
  assert.equal(parsed.MessageStatus, 'sent');
  assert.equal(parsed.ErrorCode, '');
  assert.equal(parsed.ErrorMessage, '');
  for (const field of ['AccountSid', 'MessageSid', 'From', 'To', 'Body', 'MessageStatus', 'NumMedia']) {
    assert.throws(() => parseJsonWebhook(JSON.stringify({ [field]: null })), error => error.statusCode === 400);
  }
});

test('callback query preservation and external path/encoding are independent of Host headers', () => {
  const config = createConfig({ ...ENV, SIGNALWIRE_STATUS_WEBHOOK_URL: 'https://proxy.test/prefix/%73tatus?one=a%2Fb&two=%2B1' });
  const callback = statusCallbackUrl(config, 'test-id');
  assert.equal(new URL(callback).searchParams.get('one'), 'a/b');
  assert.equal(new URL(callback).searchParams.get('two'), '+1');
  assert.equal(new URL(callback).searchParams.get('test_id'), 'test-id');
  const rawQuery = '?one=a%2Fb&two=%2B1&test_id=test-id';
  assert.equal(signedWebhookUrl(config, false, `/webhooks/signalwire/status${rawQuery}`), `https://proxy.test/prefix/%73tatus${rawQuery}`);
});

test('status verification mirrors the exact callback URL serialization used when sending', () => {
  const config = createConfig({ ...ENV, SIGNALWIRE_STATUS_WEBHOOK_URL: 'https://PROXY.TEST:443/prefix/status?fixed=a%20b' });
  const callback = new URL(statusCallbackUrl(config, 'test-id'));
  assert.equal(signedWebhookUrl(config, false, `/webhooks/signalwire/status${callback.search}`), callback.href);
});
